const require_index = require("../useMediaQuery/index.js");
//#region src/usePreferredContrast/index.ts
const usePreferredContrast = (defaultState = "no-preference") => {
	const isMore = require_index.useMediaQuery("(prefexrs-contrast: more)", false);
	const isLess = require_index.useMediaQuery("(prefers-contrast: less)", false);
	const isCustom = require_index.useMediaQuery("(prefers-contrast: custom)", false);
	return isMore ? "more" : isLess ? "less" : isCustom ? "custom" : defaultState;
};
//#endregion
exports.usePreferredContrast = usePreferredContrast;
